#include <cstdint>
#include <cstring>

struct InfoV1 { std::uint32_t cbSize; std::uint32_t processors; std::uint32_t pageSize; };
struct InfoV2 { std::uint32_t cbSize; std::uint32_t processors; std::uint32_t pageSize; std::uint32_t flags; std::uint64_t totalMemory; };

constexpr std::uint32_t ERROR_SUCCESS = 0;
constexpr std::uint32_t ERROR_INVALID_PARAMETER = 87;
constexpr std::uint32_t kProcessors = 16, kPageSize = 4096, kFlags = 0x5;
constexpr std::uint64_t kTotalMemory = 34359738368ull;
inline std::uint32_t g_lastError{ 0 };

constexpr std::uint32_t FLAG_READ = 0x1, FLAG_WRITE = 0x2, FLAG_CREATE = 0x4, FLAG_TRUNCATE = 0x8, FLAG_APPEND = 0x10, FLAG_EXCLUSIVE = 0x20;

bool fillInfo(void* info)
{
    if (info == nullptr)
    {
        g_lastError = ERROR_INVALID_PARAMETER;
        return false;
    }
    std::uint32_t size{ 0 };
    std::memcpy(&size, info, sizeof size);
    if (size == sizeof(InfoV1))
    {
        const InfoV1 v1{ size, kProcessors, kPageSize };
        std::memcpy(info, &v1, sizeof v1);
    }
    else if (size == sizeof(InfoV2))
    {
        const InfoV2 v2{ size, kProcessors, kPageSize, kFlags, kTotalMemory };
        std::memcpy(info, &v2, sizeof v2);
    }
    else
    {
        g_lastError = ERROR_INVALID_PARAMETER;
        return false;
    }
    g_lastError = ERROR_SUCCESS;
    return true;
}

std::uint32_t checkOpenFlags(std::uint32_t flags)
{
    constexpr std::uint32_t known{ FLAG_READ | FLAG_WRITE | FLAG_CREATE | FLAG_TRUNCATE | FLAG_APPEND | FLAG_EXCLUSIVE };
    const bool write{ (flags & FLAG_WRITE) != 0 };
    if ((flags & ~known) != 0) return ERROR_INVALID_PARAMETER;
    if ((flags & (FLAG_READ | FLAG_WRITE)) == 0) return ERROR_INVALID_PARAMETER;
    if ((flags & (FLAG_TRUNCATE | FLAG_APPEND)) != 0 && !write) return ERROR_INVALID_PARAMETER;
    if ((flags & FLAG_TRUNCATE) && (flags & FLAG_APPEND)) return ERROR_INVALID_PARAMETER;
    if ((flags & FLAG_EXCLUSIVE) && !(flags & FLAG_CREATE)) return ERROR_INVALID_PARAMETER;
    return ERROR_SUCCESS;
}

std::uint32_t checkDisposition(std::uint32_t value)
{
    return value >= 1 && value <= 5 ? ERROR_SUCCESS : ERROR_INVALID_PARAMETER;
}

unitTests:
#include <cstring>
TEST("version 1 and version 2") {
    InfoV1 a{};
    a.cbSize = sizeof(InfoV1);
    CHECK(fillInfo(&a));
    CHECK(a.cbSize == sizeof(InfoV1) && a.processors == 16 && a.pageSize == 4096);
    CHECK_EQ(g_lastError, 0u);
    InfoV2 b{};
    b.cbSize = sizeof(InfoV2);
    CHECK(fillInfo(&b));
    CHECK(b.processors == 16 && b.pageSize == 4096 && b.flags == 5 && b.totalMemory == 34359738368ull);
}
TEST("never writing past the size") {
    unsigned char memory[40];
    std::memset(memory, 0xCC, sizeof memory);
    const std::uint32_t size{ sizeof(InfoV1) };
    std::memcpy(memory + 1, &size, sizeof size);
    CHECK(fillInfo(memory + 1));
    bool untouched{ true };
    for (std::size_t i{ 1 + sizeof(InfoV1) }; i < sizeof memory; ++i) if (memory[i] != 0xCC) untouched = false;
    CHECK(untouched);
    CHECK_EQ(memory[0], 0xCC);
    std::uint32_t pageSize{ 0 };
    std::memcpy(&pageSize, memory + 1 + 8, sizeof pageSize);
    CHECK_EQ(pageSize, 4096u);
}
TEST("bad sizes and null") {
    InfoV1 a{};
    a.cbSize = 0;
    g_lastError = 0;
    CHECK(!fillInfo(&a));
    CHECK_EQ(g_lastError, 87u);
    CHECK_EQ(a.processors, 0u);
    a.cbSize = sizeof(InfoV1) + 1;
    CHECK(!fillInfo(&a));
    CHECK(!fillInfo(nullptr));
    CHECK_EQ(g_lastError, 87u);
}
TEST("flag rules") {
    CHECK_EQ(checkOpenFlags(FLAG_READ), 0u);
    CHECK_EQ(checkOpenFlags(FLAG_READ | FLAG_WRITE | FLAG_CREATE | FLAG_EXCLUSIVE), 0u);
    CHECK_EQ(checkOpenFlags(FLAG_WRITE | FLAG_APPEND), 0u);
    CHECK_EQ(checkOpenFlags(FLAG_WRITE | FLAG_TRUNCATE | FLAG_CREATE), 0u);
    CHECK_EQ(checkOpenFlags(0), 87u);
    CHECK_EQ(checkOpenFlags(FLAG_CREATE), 87u);
    CHECK_EQ(checkOpenFlags(FLAG_READ | FLAG_APPEND), 87u);
    CHECK_EQ(checkOpenFlags(FLAG_READ | FLAG_TRUNCATE), 87u);
    CHECK_EQ(checkOpenFlags(FLAG_WRITE | FLAG_TRUNCATE | FLAG_APPEND), 87u);
    CHECK_EQ(checkOpenFlags(FLAG_WRITE | FLAG_EXCLUSIVE), 87u);
    CHECK_EQ(checkOpenFlags(FLAG_READ | 0x40), 87u);
    CHECK_EQ(checkOpenFlags(FLAG_READ | 0x80000000u), 87u);
}
TEST("one value, not flags") {
    CHECK_EQ(checkDisposition(1), 0u);
    CHECK_EQ(checkDisposition(3), 0u);
    CHECK_EQ(checkDisposition(5), 0u);
    CHECK_EQ(checkDisposition(0), 87u);
    CHECK_EQ(checkDisposition(6), 87u);
    CHECK_EQ(checkDisposition(1 | 4), 0u);
    CHECK_EQ(checkDisposition(2 | 4), 87u);
}

